BEGIN;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f10bd630-6e35-4513-a9b3-4908d1b00c3c',true);
DO $test$
DECLARE org uuid:='85acbac0-e8b4-434c-a22b-3ec13b55e1a7';party uuid:='d86a111c-d392-4f09-adc1-13f9e72a1c53';bank uuid;cid uuid;mid uuid;rec uuid;cash uuid;profit uuid;ret uuid;loss uuid;flow uuid;cp jsonb;p jsonb;r jsonb;err text;v numeric;cl uuid;pay uuid;allocs jsonb:='[]';b record;remaining numeric;
BEGIN
 bank:=(open_financial_account(jsonb_build_object('request_id',gen_random_uuid(),'scope','ORGANIZATION','organization_id',org,'type','BANK','name','QA participation rollback bank','currency','SAR','opening_balance',1000,'opening_date','2026-01-01','fx_rate',1))->>'id')::uuid;
 cp:=jsonb_build_object('organization_id',org,'request_id',gen_random_uuid(),'counterparty_id',party,'entity_id',null,'reference','QA-PARTICIPATION','description','QA actual profit participation','project','QA investor pool','capital',1000,'currency','SAR','exchange_rate',1,'start_date','2026-01-01','maturity_date','2027-01-01','investor_profit_pct',30,'investor_loss_pct',100,'capital_treatment','FINANCING','accounting_basis','Contractual variable redeemable participation liability','exit_terms','Capital returned on approved withdrawal after reconciled results','loss_terms','Investor bears allocated losses up to remaining capital','variable_return',true);
 cid:=(create_participation_contract(cp)->>'id')::uuid;
 IF(create_participation_contract(cp)->>'id')::uuid<>cid THEN RAISE EXCEPTION 'PARTICIPATION_CREATE_REPLAY';END IF;
 p:=jsonb_build_object('organization_id',org,'contract_id',cid,'request_id',gen_random_uuid(),'kind','CAPITAL_RECEIPT','amount',100,'date','2026-01-01','account_id',bank,'reason','QA cancelled receipt before any cash movement');
 r:=prepare_participation_movement(p);mid:=(r->>'id')::uuid;SELECT flow_id INTO flow FROM participation_movements WHERE id=mid;
 PERFORM cancel_participation_movement(mid,'QA cancelled duplicate receipt before execution');
 IF EXISTS(SELECT 1 FROM liquidity_flows WHERE id=flow)THEN RAISE EXCEPTION 'CANCELLED_RECEIPT_FORECAST_REMAINS';END IF;
 p:=jsonb_set(p,'{request_id}',to_jsonb(gen_random_uuid()));p:=jsonb_set(p,'{amount}','1000');r:=prepare_participation_movement(p);mid:=(r->>'id')::uuid;rec:=(r->>'eventId')::uuid;cash:=(r->>'cashEventId')::uuid;
 BEGIN PERFORM post_participation_movement(mid);err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'VALID_APPROVAL_REQUIRED'THEN RAISE EXCEPTION 'PARTICIPATION_APPROVAL_GUARD:%',err;END IF;
 IF(SELECT current_balance FROM liquidity_accounts WHERE id=bank)<>1000 THEN RAISE EXCEPTION 'PREPARED_RECEIPT_MOVED_BANK';END IF;
 PERFORM approve_financial_event(rec,'QA capital recognition approval');PERFORM approve_financial_event(cash,'QA capital receipt approval');PERFORM post_participation_movement(mid);PERFORM post_participation_movement(mid);
 IF(SELECT current_balance FROM liquidity_accounts WHERE id=bank)<>2000 THEN RAISE EXCEPTION 'CAPITAL_RECEIPT_NOT_ONCE';END IF;
 IF EXISTS(SELECT 1 FROM financial_event_obligations WHERE event_id=rec)THEN RAISE EXCEPTION 'VARIABLE_CAPITAL_BECAME_FIXED_DEBT';END IF;
 p:=jsonb_build_object('organization_id',org,'contract_id',cid,'request_id',gen_random_uuid(),'kind','PROFIT','period_result',200,'period_from','2026-01-01','period_to','2026-03-31','date','2026-03-31','reason','QA reviewed actual period profit before investor allocation');
 r:=prepare_participation_movement(p);profit:=(r->>'id')::uuid;
 IF(r->>'amount')::numeric<>60 THEN RAISE EXCEPTION 'INVESTOR_PROFIT_NOT_60';END IF;
 PERFORM approve_financial_event((r->>'eventId')::uuid,'QA investor profit approval');PERFORM post_participation_movement(profit);
 BEGIN PERFORM prepare_participation_movement(jsonb_set(p,'{request_id}',to_jsonb(gen_random_uuid())));err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PARTICIPATION_PERIOD_ALREADY_DECLARED'THEN RAISE EXCEPTION 'DUPLICATE_PERIOD_GUARD:%',err;END IF;
 p:=jsonb_build_object('organization_id',org,'contract_id',cid,'request_id',gen_random_uuid(),'kind','LOSS','period_result',100,'period_from','2026-04-01','period_to','2026-04-30','date','2026-04-30','reason','QA reviewed actual loss allocated under the contract');
 r:=prepare_participation_movement(p);loss:=(r->>'id')::uuid;PERFORM approve_financial_event((r->>'eventId')::uuid,'QA loss allocation approval');PERFORM post_participation_movement(loss);
 p:=jsonb_build_object('organization_id',org,'contract_id',cid,'request_id',gen_random_uuid(),'kind','CAPITAL_RETURN','amount',1000,'date','2026-05-01','reason','QA return capital after loss allocation and review');
 BEGIN PERFORM prepare_participation_movement(p);err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PARTICIPATION_AVAILABLE_CAPITAL_EXCEEDED'THEN RAISE EXCEPTION 'EXCESS_CAPITAL_RETURN_GUARD:%',err;END IF;
 p:=jsonb_set(p,'{amount}','900');r:=prepare_participation_movement(p);ret:=(r->>'id')::uuid;PERFORM approve_financial_event((r->>'eventId')::uuid,'QA capital return approval');PERFORM post_participation_movement(ret);
 IF(SELECT current_balance FROM liquidity_accounts WHERE id=bank)<>2000 THEN RAISE EXCEPTION 'DECLARATION_MOVED_BANK';END IF;
 IF(SELECT sum(b.outstanding_base_amount)FROM financial_event_obligation_balances b JOIN participation_movements m ON m.recognition_event_id=b.event_id WHERE m.contract_id=cid)<>960 THEN RAISE EXCEPTION 'INVESTOR_CLAIM_NOT_960';END IF;
 BEGIN PERFORM finish_participation_contract(cid,'CLOSE','QA premature closure while distributions are outstanding');err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PARTICIPATION_OPEN_CAPITAL_OR_DISTRIBUTIONS'THEN RAISE EXCEPTION 'EARLY_CLOSE_GUARD:%',err;END IF;
 SELECT id INTO cl FROM financial_classifications WHERE organization_id=org AND classification_type='PAYABLE'AND active LIMIT 1;
 pay:=create_financial_event_command(jsonb_build_object('organization_id',org,'entity_id',null,'counterparty_id',party,'event_type','SETTLEMENT','source_module','OPERATIONAL_CONSOLE','source_event_key','qa-participation-pay:'||gen_random_uuid(),'event_date','2026-05-01','due_date',null,'base_currency','SAR','description','QA participation capital and profit payout','lines',jsonb_build_array(jsonb_build_object('line_number',1,'classification_id',cl,'description','Investor capital and profit payout','amount',960,'currency','SAR','exchange_rate',1,'base_amount',960,'cash_direction','OUTFLOW','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0)),'obligations','[]'::jsonb,'links','[]'::jsonb));
 FOR b IN SELECT b.* FROM financial_event_obligation_balances b JOIN participation_movements m ON m.recognition_event_id=b.event_id WHERE m.contract_id=cid AND b.outstanding_base_amount>0 LOOP flow:=ensure_debt_flow(b.obligation_id);allocs:=allocs||jsonb_build_array(jsonb_build_object('obligation_id',b.obligation_id,'flow_id',flow,'amount',b.outstanding_base_amount,'base_amount',b.outstanding_base_amount,'flow_amount',b.outstanding_base_amount,'flow_currency','SAR','flow_exchange_rate',1));END LOOP;
 PERFORM transition_financial_event(pay,'PLANNED','QA');PERFORM transition_financial_event(pay,'COMMITTED','QA');PERFORM approve_financial_event(pay,'QA payout approval');PERFORM post_financial_settlement(pay,bank,'OUTFLOW','2026-05-01',960,'SAR',1,960,allocs);
 IF(SELECT current_balance FROM liquidity_accounts WHERE id=bank)<>1040 THEN RAISE EXCEPTION 'PARTICIPATION_PAYOUT_RECONCILIATION';END IF;
 PERFORM finish_participation_contract(cid,'CLOSE','QA fully reconciled closure after all investor claims paid');
 PERFORM set_config('qa.participation.result',jsonb_build_object('capital_received',1000,'actual_profit',200,'investor_profit',60,'investor_loss',100,'capital_return',900,'cash_payout',960,'bank_after',1040,'period_guard',true,'close_guard',true,'rollback',true)::text,true);
END $test$;
SELECT current_setting('qa.participation.result')::jsonb result;
ROLLBACK;
